Question
hello, we recently ran into an issue when testing histogram metrics through the opentelemetry source component.
we have this client code (based on these docs):
import time

from dotenv import load_dotenv
from opentelemetry.exporter.otlp.proto.http.metric_exporter import OTLPMetricExporter
from opentelemetry.metrics import Observation
from opentelemetry.sdk.metrics import (
    Counter,
    Histogram,
    # _Gauge,
    MeterProvider,
    ObservableCounter,
    ObservableGauge,
    ObservableUpDownCounter,
    UpDownCounter,
)
from opentelemetry.sdk.metrics.export import (
    AggregationTemporality,
    PeriodicExportingMetricReader,
)

load_dotenv()

exporter = OTLPMetricExporter(
    endpoint="http://vector_collector_default:4318/v1/metrics",
    preferred_temporality={
        Counter: AggregationTemporality.DELTA,
        UpDownCounter: AggregationTemporality.CUMULATIVE,
        # Gauge was missing in their recommendation docs - can add this based on ObservableGauge
        # Python SDK maybe prefers ObservableGauge (_Gauge is protected) so we'll try that instead
        # _Gauge: AggregationTemporality.CUMULATIVE,
        Histogram: AggregationTemporality.DELTA,
        ObservableCounter: AggregationTemporality.DELTA,
        ObservableUpDownCounter: AggregationTemporality.CUMULATIVE,
        ObservableGauge: AggregationTemporality.CUMULATIVE,
    },
)
reader = PeriodicExportingMetricReader(exporter, export_interval_millis=5_000)
provider = MeterProvider(metric_readers=[reader])

meter = provider.get_meter("my-meter")
counter = meter.create_counter("test.recommended.vector.counter")
updown = meter.create_up_down_counter("test.recommended.vector.updown")
observableGauge = meter.create_observable_gauge(
    name="test.recommended.vector.gauge",
    callbacks=[lambda options: [Observation(1, {})]],
)
histogram = meter.create_histogram("test.recommended.vector.histogram")

while True:
    # observable gauge uses callback, so no need to set
    counter.add(1)
    updown.add(1)
    histogram.record(1)

    time.sleep(2)

