i found this discussion about using protobuf and vrl to remap the event so i tweaked the client code slightly and targeted a different vector using an otel sink (targeting datadog otlp metric intake) with this config:
[log_schema]
level_key = "status"
level = "info"

[api]
enabled = true
address = "0.0.0.0:8787"
playground = false

[sources.opentelemetry]
type = "opentelemetry"
grpc.address = "0.0.0.0:4317"
http.address = "0.0.0.0:4318"

[transforms.convert_metric_to_log]
type   = "metric_to_log"
inputs = ["opentelemetry.metrics"]

[transforms.route_metrics]
type = "exclusive_route"
inputs = ["convert_metric_to_log"]

    [[transforms.route_metrics.routes]]
    name = "histogram"
    condition = 'exists(.aggregated_histogram)'

    [[transforms.route_metrics.routes]]
    name = "gauge"
    condition = 'exists(.gauge)'

    [[transforms.route_metrics.routes]]
    name = "counter"
    condition = 'exists(.counter)'

[transforms.remap_histogram]
type = "remap"
inputs = ["route_metrics.histogram"]
source = '''
# pull out tags
attrs = []
for_each(object!(.tags)) -> |k, v| {
  attrs = push(attrs, {
    "key": k,
    "value": { "stringValue": to_string!(v) }
  })
}

# get bucket counts and explicit bounds
bucket_counts = []
explicit_bounds = []
for_each(array!(.aggregated_histogram.buckets)) -> |_index, bucket| {
  if (bucket.upper_limit != "inf") {
    bucket_counts = push(bucket_counts, bucket.count)
    explicit_bounds = push(explicit_bounds, bucket.upper_limit)
  }
}

# get count and sum
count = .aggregated_histogram.count
sum = .aggregated_histogram.sum

# timestamp
unix_timestamp = to_unix_timestamp!(.timestamp, unit: "nanoseconds")

# fill in the otel histogram format
. = {
  "resourceMetrics": [
    {
      "resource": {
        "attributes": attrs
      },
      "scopeMetrics": [
        {
          "metrics": [
            {
              "histogram": {
                # TODO: verify CUMULATIVE vs DELTA
                # this needs to be set to DELTA, if histograms are sent as CUMULATIVE it will be rejected by Datadog
                "aggregationTemporality": "AGGREGATION_TEMPORALITY_DELTA",
                "dataPoints": [
                  {
                    "bucketCounts": bucket_counts,
                    "explicitBounds": explicit_bounds,
                    # TODO: min and max aren't included in the vector metric output
                    # see if there is an impact when these aren't included
                    # "min": 1.0,
                    # "max": 1.0,
                    "count": count,
                    "sum": sum,
                    # these timestamps are required or metric doesn't appear
                    "startTimeUnixNano": unix_timestamp,
                    "timeUnixNano": unix_timestamp
                  }
                ]
              },
              "name": .name
            }
          ],
          "scope": {
            "name": "my-meter"
          }
        }
      ]
    }
  ],
  "timestamp": .timestamp
}
'''

[transforms.remap_counter]
type = "remap"
inputs = ["route_metrics.counter"]
source = '''
# pull out tags
attrs = []
for_each(object!(.tags)) -> |k, v| {
  attrs = push(attrs, {
    "key": k,
    "value": { "stringValue": to_string!(v) }
  })
}

# timestamp
unix_timestamp = to_unix_timestamp!(.timestamp, unit: "nanoseconds")

. = {
  "resourceMetrics": [
    {
      "resource": {
        "attributes": attrs
      },
      "scopeMetrics": [
        {
          "metrics": [
            {
              "name": .name,
              "sum": {
                "aggregationTemporality": "AGGREGATION_TEMPORALITY_DELTA",
                "dataPoints": [
                  {
                    "asInt": to_int!(.counter.value),
                    "startTimeUnixNano": unix_timestamp,
                    "timeUnixNano": unix_timestamp
                  }
                ],
                "isMonotonic": true
              }
            },
          ],
          "scope": {
            "name": "my-meter"
          }
        }
      ]
    }
  ],
  "timestamp": .timestamp
}
'''

[transforms.remap_gauge]
type = "remap"
inputs = ["route_metrics.gauge"]
source = '''
# pull out tags
attrs = []
for_each(object!(.tags)) -> |k, v| {
  attrs = push(attrs, {
    "key": k,
    "value": { "stringValue": to_string!(v) }
  })
}

# timestamp
unix_timestamp = to_unix_timestamp!(.timestamp, unit: "nanoseconds")

. = {
  "resourceMetrics": [
    {
      "resource": {
        "attributes": attrs
      },
      "scopeMetrics": [
        {
          "metrics": [
            {
              "gauge": {
                "dataPoints": [
                  {
                    "asInt": to_int!(.gauge.value),
                    "timeUnixNano": unix_timestamp
                  }
                ]
              },
              "name": .name
            }
          ],
          "scope": {
            "name": "my-meter"
          }
        }
      ]
    }
  ],
  "timestamp": .timestamp
}
'''

[sinks.otlp_metrics_intake_sink]
type   = "opentelemetry"
inputs = ["remap_histogram", "remap_counter", "remap_gauge"]
protocol.type = "http"
protocol.uri  = "https://otlp.datadoghq.com/v1/metrics"
protocol.method = "post"
protocol.encoding.codec = "otlp"
protocol.headers."dd-api-key" = "${DD_API_KEY}"
protocol.headers."content-type" = "application/x-protobuf"
protocol.headers."dd-otel-metric-config" = '{"resource_attributes_as_tags": true, "instrumentation_scope_metadata_as_tags": true, "histograms": {"mode": "distributions", "send_aggregation_metrics": true}}'

this results in the desired avg of 1.0

thinking it could be issue with the dd apis, i opened a support ticket with them but they redirected me here.  any ideas if this is an issue with the dd metrics sink?  or something else entirely?  thanks for your time.
